insert into public.place_translations (place_id, lang, name, short_desc, best_time)
select p.id, v.lang, v.name, v.short_desc, v.best_time
from (values
  ('ayasofya', 'tr', 'Ayasofya', '537''de I. Justinianus döneminde tamamlanan dev kubbeli yapı; kilise, cami ve müze olarak kullanıldı, bugün yeniden cami.', null),
  ('ayasofya', 'en', 'Hagia Sophia', 'The great domed building completed under Justinian I in 537; it has served as church, mosque and museum, and is a mosque again today.', null),
  ('sultanahmet-camii', 'tr', 'Sultanahmet Camii', '1609-1616 arasında yapılan, altı minaresi ve içindeki mavi İznik çinileriyle tanınan cami.', null),
  ('sultanahmet-camii', 'en', 'Blue Mosque', 'Built between 1609 and 1616, famous for its six minarets and the blue İznik tiles inside.', null),
  ('suleymaniye-camii', 'tr', 'Süleymaniye Camii', 'Mimar Sinan''ın Kanuni Sultan Süleyman için yaptığı, Haliç''e tepeden bakan külliyenin merkezi.', null),
  ('suleymaniye-camii', 'en', 'Süleymaniye Mosque', 'Mimar Sinan''s mosque for Suleiman the Magnificent, crowning a complex above the Golden Horn.', null),
  ('kariye-camii', 'tr', 'Kariye Camii', 'Bizans dönemi mozaik ve freskleriyle ünlü eski Khora Kilisesi; bugün cami olarak kullanılıyor.', null),
  ('kariye-camii', 'en', 'The Chora', 'The former Chora Church, famous for its Byzantine mosaics and frescoes; used as a mosque today.', null),
  ('kucuk-ayasofya-camii', 'tr', 'Küçük Ayasofya Camii', '6. yüzyılda Sergios ve Bakkhos Kilisesi olarak yapılan, Ayasofya''dan eski Bizans yapısı.', null),
  ('kucuk-ayasofya-camii', 'en', 'Little Hagia Sophia', 'Built in the 6th century as the Church of Saints Sergius and Bacchus, older than Hagia Sophia itself.', null),
  ('sokollu-mehmed-pasa-camii', 'tr', 'Sokollu Mehmed Paşa Camii', 'Mimar Sinan''ın Kadırga''da Sokollu Mehmed Paşa için yaptığı, iç mekândaki İznik çinileriyle bilinen cami.', null),
  ('sokollu-mehmed-pasa-camii', 'en', 'Sokullu Mehmed Pasa Mosque', 'Mimar Sinan''s mosque for Sokollu Mehmed Pasha in Kadırga, known for the İznik tiles inside.', null),
  ('sehzade-camii', 'tr', 'Şehzade Camii', 'Kanuni''nin genç yaşta ölen oğlu Şehzade Mehmed için yaptırdığı, Mimar Sinan''ın ilk büyük selatin camisi.', null),
  ('sehzade-camii', 'en', 'The Şehzade Mosque', 'Built by Suleiman for his son Prince Mehmed, who died young; Mimar Sinan''s first great imperial mosque.', null),
  ('fethiye-camii', 'tr', 'Fethiye Camii', 'Pammakaristos Kilisesi olarak yapılan, ek şapelindeki Bizans mozaikleriyle bilinen yapı.', null),
  ('fethiye-camii', 'en', 'Fethiye Mosque (Pammakaristos)', 'Built as the Pammakaristos Church; its side chapel holds fine Byzantine mosaics.', null),
  ('laleli-camii', 'tr', 'Laleli Camii', '18. yüzyılda III. Mustafa döneminde yapılan, Osmanlı barok üslubunun önemli örneklerinden.', null),
  ('laleli-camii', 'en', 'Laleli Mosque', 'Built under Mustafa III in the 18th century, a leading example of Ottoman Baroque.', null),
  ('yeni-cami', 'tr', 'Yeni Cami', 'Eminönü meydanına hâkim, yapımı yarım yüzyılı aşan büyük cami; Mısır Çarşısı da külliyesinin parçası.', null),
  ('yeni-cami', 'en', 'New Mosque', 'The great mosque overlooking Eminönü square, built over more than half a century; the Spice Bazaar belongs to its complex.', null),
  ('zeyrek-camii', 'tr', 'Zeyrek Camii', '12. yüzyıldan kalma Pantokrator Manastırı''nın kiliselerinden dönüştürülen, Bizans''ın en büyük yapı topluluklarından.', null),
  ('zeyrek-camii', 'en', 'Molla Zeyrek Mosque', 'Converted from the churches of the 12th-century Pantokrator Monastery, one of Byzantium''s largest religious complexes.', null),
  ('nuruosmaniye-camii', 'tr', 'Nuruosmaniye Camii', 'Kapalıçarşı''nın kapısında, Osmanlı barok üslubunun ilk büyük camisi.', null),
  ('nuruosmaniye-camii', 'en', 'Nuruosmaniye Mosque', 'At the gate of the Grand Bazaar, the first great mosque in the Ottoman Baroque style.', null),
  ('ortakoy-camii', 'tr', 'Ortaköy Camii', 'Boğaz Köprüsü''nün hemen altında, deniz kıyısında duran zarif 19. yüzyıl camisi.', 'Gün batımı'),
  ('ortakoy-camii', 'en', 'Ortaköy Mosque', 'An elegant 19th-century mosque right on the water beneath the Bosphorus Bridge.', 'Sunset'),
  ('fatih-camii', 'tr', 'Fatih Camii', 'Fatih Sultan Mehmed''in yaptırdığı, 1766 depreminden sonra yeniden inşa edilen büyük külliye.', null),
  ('fatih-camii', 'en', 'Fatih Istanbul Mosque', 'The great complex founded by Mehmed the Conqueror, rebuilt after the earthquake of 1766.', null),
  ('bodrum-camii', 'tr', 'Bodrum Camii', '10. yüzyılda Myrelaion Kilisesi olarak yapılan küçük Bizans yapısı.', null),
  ('bodrum-camii', 'en', 'Myrelaion (Bodrum Mosque)', 'A small Byzantine building, built in the 10th century as the Myrelaion Church.', null),
  ('rustem-pasa-camii', 'tr', 'Rüstem Paşa Camii', 'Tahtakale''de dükkânların üzerine yükseltilmiş, İznik çinileriyle kaplı Mimar Sinan camisi.', null),
  ('rustem-pasa-camii', 'en', 'Rüstem Pasha Mosque', 'A Mimar Sinan mosque in Tahtakale, raised above a row of shops and covered in İznik tiles.', null),
  ('bayezid-camii', 'tr', 'Bayezid Camii', 'II. Bayezid''in yaptırdığı, İstanbul''da günümüze ulaşan en eski selatin camilerinden.', null),
  ('bayezid-camii', 'en', 'Bayezid II Mosque', 'Built by Bayezid II, one of the oldest surviving imperial mosques in Istanbul.', null),
  ('mihrimah-sultan-camii-edirnekapi', 'tr', 'Mihrimah Sultan Camii (Edirnekapı)', 'Surların yanında, eski şehrin en yüksek noktasında, çok sayıda penceresiyle ışık dolu Mimar Sinan camisi.', null),
  ('mihrimah-sultan-camii-edirnekapi', 'en', 'Mihrimah Edirnekapı Mosque', 'A light-filled Mimar Sinan mosque with countless windows, by the city walls at the old city''s highest point.', null),
  ('dolmabahce-camii', 'tr', 'Dolmabahçe Camii', 'Dolmabahçe Sarayı''nın yanında, Boğaz kıyısında 1855''te tamamlanan cami.', null),
  ('dolmabahce-camii', 'en', 'Dolmabahçe Mosque', 'Completed in 1855 on the Bosphorus shore, next to Dolmabahçe Palace.', null),
  ('eyup-sultan-camii', 'tr', 'Eyüp Sultan Camii', 'Ebu Eyyub el-Ensari''nin türbesinin yanında kurulan, İstanbul''un en çok ziyaret edilen camilerinden.', null),
  ('eyup-sultan-camii', 'en', 'Eyüp Sultan Mosque', 'Built beside the tomb of Abu Ayyub al-Ansari, one of the most visited mosques in Istanbul.', null),
  ('camlica-camii', 'tr', 'Çamlıca Camii', 'Küçük Çamlıca Tepesi''nde, 2019''da açılan Türkiye''nin en büyük camisi.', null),
  ('camlica-camii', 'en', 'Grand Çamlıca Mosque', 'Turkey''s largest mosque, opened in 2019 on Küçük Çamlıca Hill.', null),
  ('arap-camii', 'tr', 'Arap Camii', 'Galata''da, Dominiken kilisesi olarak yapılan ve çan kulesi minareye dönüştürülen Gotik yapı.', null),
  ('arap-camii', 'en', 'Arap Mosque', 'A Gothic building in Galata, built as a Dominican church; its bell tower became the minaret.', null),
  ('yavuz-selim-camii', 'tr', 'Yavuz Selim Camii', 'Kanuni''nin babası Yavuz Sultan Selim için yaptırdığı, Haliç''e bakan sade ve görkemli cami.', null),
  ('yavuz-selim-camii', 'en', 'Yavuz Sultan Selim Mosque', 'Built by Suleiman for his father Selim I, a simple yet grand mosque overlooking the Golden Horn.', null),
  ('yeni-valide-camii', 'tr', 'Yeni Valide Camii', 'Üsküdar''da 18. yüzyılın başında Gülnuş Emetullah Sultan için yapılan büyük külliye.', null),
  ('yeni-valide-camii', 'en', 'Yeni Üsküdar Mosque', 'A large complex in Üsküdar built in the early 18th century for Gülnuş Emetullah Sultan.', null),
  ('mihrimah-sultan-camii-uskudar', 'tr', 'Mihrimah Sultan Camii (Üsküdar)', 'Üsküdar iskelesinin karşısında, Mimar Sinan''ın Mihrimah Sultan için yaptığı ilk cami.', null),
  ('mihrimah-sultan-camii-uskudar', 'en', 'Mihrimah Sultan Mosque', 'Facing the Üsküdar pier, the first mosque Mimar Sinan built for Mihrimah Sultan.', null),
  ('kilic-ali-pasa-camii', 'tr', 'Kılıç Ali Paşa Camii', 'Tophane''de, Kaptan-ı Derya Kılıç Ali Paşa için Mimar Sinan''ın yaptığı, Ayasofya''dan esinlenen cami.', null),
  ('kilic-ali-pasa-camii', 'en', 'Kılıç Ali Pasha Mosque', 'Mimar Sinan''s mosque in Tophane for Admiral Kılıç Ali Pasha, inspired by Hagia Sophia.', null),
  ('sakirin-camii', 'tr', 'Şakirin Camii', 'Karacaahmet''te 2009''da açılan, iç tasarımını bir kadın mimarın yaptığı modern cami.', null),
  ('sakirin-camii', 'en', 'Şakirin Mosque', 'A modern mosque in Karacaahmet, opened in 2009, with an interior designed by a woman.', null),
  ('aya-yorgi-patrikhane-kilisesi', 'tr', 'Aya Yorgi Patrikhane Kilisesi', 'Fener''de, Ekümenik Patrikhanenin merkezi olan Rum Ortodoks kilisesi.', null),
  ('aya-yorgi-patrikhane-kilisesi', 'en', 'Church of St. George', 'The Greek Orthodox church in Fener that serves as the seat of the Ecumenical Patriarchate.', null),
  ('st-antuan-katolik-kilisesi', 'tr', 'St. Antuan Katolik Kilisesi', 'İstiklal Caddesi''nde, İstanbul''un en büyük Katolik kilisesi; neo-Gotik cephesiyle dikkat çeker.', null),
  ('st-antuan-katolik-kilisesi', 'en', 'Church of Saint Anthony of Padua', 'Istanbul''s largest Catholic church, on İstiklal Avenue, with a striking neo-Gothic façade.', null),
  ('meryem-ana-kilisesi', 'tr', 'Meryem Ana Kilisesi', 'Ayvansaray''da, Bizans döneminden beri kutsal sayılan ayazmasıyla bilinen Vlaherna Meryem Ana Kilisesi.', null),
  ('meryem-ana-kilisesi', 'en', 'Church of St. Mary of Blachernae', 'The Church of St. Mary of Blachernae in Ayvansaray, known for its holy spring revered since Byzantine times.', null),
  ('saint-esprit-kilisesi', 'tr', 'Saint Esprit Kilisesi', 'Harbiye''de, 19. yüzyılda yapılan Katolik katedrali.', null),
  ('saint-esprit-kilisesi', 'en', 'Cathedral of the Holy Spirit', 'A Catholic cathedral in Harbiye, built in the 19th century.', null),
  ('balikli-meryem-ana-rum-manastiri', 'tr', 'Balıklı Meryem Ana Rum Manastırı', 'Zeytinburnu''nda, içinde balıkların yüzdüğü ayazmasıyla ünlü Rum Ortodoks manastırı.', null),
